#!/usr/bin/env python3
from pathlib import Path
import subprocess, shutil, datetime, sys, base64

ROOT = Path.cwd()
APP = ROOT / "src/App.tsx"
HELPER = ROOT / "src/lib/platformApi.ts"
COMPONENT = ROOT / "src/PlatformApiManager.tsx"
STYLE = ROOT / "src/PlatformApiManager.css"

def stop(message):
    print("ERREUR :", message)
    sys.exit(1)

if not (ROOT / ".git").exists():
    stop("Lance ce script depuis la racine du dépôt KALYNO-admin.")
branch = subprocess.run(["git", "branch", "--show-current"], cwd=ROOT, text=True, capture_output=True).stdout.strip()
if branch != "feat/platform-api-v1":
    stop(f"Branche attendue : feat/platform-api-v1 ; branche actuelle : {branch or 'inconnue'}.")
status = subprocess.run(["git", "status", "--porcelain"], cwd=ROOT, text=True, capture_output=True).stdout.strip()
if status:
    stop("Le dépôt contient des modifications locales. Sauvegarde/commit-les avant installation ; aucun fichier n'a été modifié.")
for p in (APP, HELPER):
    if not p.is_file(): stop(f"Fichier requis absent : {p.relative_to(ROOT)}")
for p in (COMPONENT, STYLE):
    if p.exists(): stop(f"{p.relative_to(ROOT)} existe déjà. Arrêt sans écrasement.")
app = APP.read_text()
helper = HELPER.read_text()
anchors = [
    ('type Section = "frenchstudio" | "overview"', 'type Section = "frenchstudio" | "platformapi" | "overview"'),
    ('import FrenchConcoursStudio from "./FrenchConcoursStudio";', 'import FrenchConcoursStudio from "./FrenchConcoursStudio";\nimport PlatformApiManager from "./PlatformApiManager";'),
    ('{ id: "frenchstudio" as Section, label: "Studio français · Concours", icon: BookOpen },', '{ id: "frenchstudio" as Section, label: "Studio français · Concours", icon: BookOpen },\n    { id: "platformapi" as Section, label: "Platform API · Console", icon: Cloud },'),
    ('{section === "frenchstudio" && <FrenchConcoursStudio />}', '{section === "frenchstudio" && <FrenchConcoursStudio />}\n          {section === "platformapi" && <PlatformApiManager />}'),
]
for old, new in anchors:
    if old not in app: stop("Point d’intégration App.tsx introuvable : " + old)
if "getPlatformHealth" in helper or "PlatformCapabilities" in helper:
    stop("Le helper semble déjà amélioré ; installation annulée pour éviter un écrasement.")
stamp = datetime.datetime.now().strftime("%Y%m%d-%H%M%S")
backup = ROOT / f".kalyno-backup-platform-console-{stamp}"
backup.mkdir()
shutil.copy2(APP, backup / "App.tsx")
shutil.copy2(HELPER, backup / "platformApi.ts")
new_app = app
for old, new in anchors: new_app = new_app.replace(old, new, 1)
(APP).write_text(new_app)
(HELPER).write_text(base64.b64decode("").decode())
COMPONENT.write_text(base64.b64decode("").decode())
STYLE.write_text(base64.b64decode("").decode())
print("Installation terminée.")
print("Sauvegarde :", backup.relative_to(ROOT))
print("Fichiers créés : src/PlatformApiManager.tsx, src/PlatformApiManager.css")
print("Fichiers modifiés : src/App.tsx, src/lib/platformApi.ts")
print("Étape suivante : npm test && npm run build")
print("Ne déploie pas avant validation des deux commandes.")
